export function convertToNumber(value) {
    if (!value) {
        return null;
    }
    if (typeof value === "number") {
        return value;
    }
    return Number.parseFloat(value);
}
export function convertValues(item) {
    const weight = convertToNumber(item.weight);
    const pricePerKilo = convertToNumber(item.pricePerKilo);
    return {
        ...item,
        weight,
        pricePerKilo
    };
}
